package net.officefloor.hq.app.claim;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves the claim to the status the action leads to; refuses a change its status does not allow, and an open,
 * settle or void by a role the sheet's permission matrix does not allow it to. Opening gives
 * the claim the sheet's next number (or, while the sheet's period numbering is on, the next in its period: <period>-<n>,
 * X-<n> for a claim in no period) and records who opened it; a voided claim keeps its number (never reused). The one who opened a
 * claim cannot settle it, and a clerk (any name not made a steward) settles a claim only when its due is at or below
 * the sheet's clerk limit (a due of n/a is within any limit; no limit when the sheet has none): a clerk settling one
 * above it leaves it PENDING instead. Only a steward approves a PENDING claim (it is settled, its due fixed at its live
 * figure then) or rejects it, with a reason that is not blank (it is OPEN again); the one who opened it cannot approve it. Settling fixes the claim's due at the rate of the grade its
 * person had on the claim's date, in force on the claim's date, at least the sheet's floor (or at the figure its person's last statement bound it to), plus its late charge on the sheet's today (none when no rate applies then, so it stays live). A claim deferred until after the sheet's today cannot be settled. A claim whose due is above the sheet's proof threshold in force on the claim's date cannot be settled or approved while it has no proof — refused before the clerk limit is considered. A claim dated in a closed period cannot change status. Returns the claim's number for the
 * audit.
 */
public class ApplyClaimStatus {
    public String apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
            @Val Sheet sheet, RoleRepository roles,
            @RequestHeader(name = "X-User", required = false) String userHeader,
            @RequestParam(name = "reason", required = false) String reason) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusException("A claim in a closed period cannot change status.");
        }
        String role = roles.roleOf(claim.getSheetId(), user);
        if (("open".equals(action) || "settle".equals(action) || "void".equals(action)) && !sheet.allows(action, role)) {
            throw new ClerkLimitException("A " + role + " cannot " + action + " a claim.");
        }
        if ("open".equals(action) && claim.getStatus().after(action) != null) {
            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
            boolean perPeriod = sheet.periodNumberingOn();
            if (perPeriod) {
                repository.lockSheet(claim.getSheetId());
            } else {
                repository.takeNextNumber(claim.getSheetId());
            }
            entityManager.refresh(claim);
            ClaimStatus next = check(claim, action);
            if (perPeriod) {
                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                        .filter(p -> p.contains(claim.getDate())).map(Period::getName).findFirst().orElse(null);
                String seq = prefix == null ? "X" : "P:" + prefix;
                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
            } else {
                claim.setNumber(String.valueOf(repository.lastNumber(claim.getSheetId())));
            }
            claim.setStatus(next);
            claim.setOpenedBy(user);
        } else {
            ClaimStatus next = check(claim, action);
            boolean steward = Role.STEWARD.equals(role);
            if (("approve".equals(action) || "reject".equals(action)) && !steward) {
                throw new ClerkLimitException("Only a steward can approve or reject a pending claim.");
            }
            if ("reject".equals(action) && (reason == null || reason.isBlank())) {
                throw new ClaimStatusException("A rejection needs a reason.");
            }
            if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
                throw new ClaimStatusException("A deferred claim cannot be settled until the sheet's today reaches its date.");
            }
            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
                throw new ClaimStatusException("The one who opened a claim cannot settle or approve it.");
            }
            if (next == ClaimStatus.SETTLED) {
                BigDecimal due = people.findById(claim.getPersonId())
                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                                grades.gradesOf(p), sheet).due(claim))
                        .orElse(null);
                BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
                if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                    throw new ProofRequiredException("A claim whose due is above the proof threshold needs a proof to be settled or approved.");
                }
                BigDecimal limit = sheet.getClerkLimit();
                if ("settle".equals(action) && limit != null && due != null && due.compareTo(limit) > 0 && !steward) {
                    next = ClaimStatus.PENDING;
                } else {
                    claim.setDue(due);
                }
            }
            claim.setStatus(next);
        }
        repository.saveAndFlush(claim);
        return claim.getNumber();
    }

    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
        ClaimStatus next = claim.getStatus().after(action);
        if (next == null) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
        }
        return next;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;

/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
public final class ClaimRules {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");

    private ClaimRules() {
    }

    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField)
            throws InvalidClaimException {
        String amount = amountField == null ? "" : amountField.trim();
        String date = dateField == null ? "" : dateField.trim();
        String note = noteField == null ? "" : noteField.trim();
        String corrects = correctsField == null ? "" : correctsField.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Corrects must be a claim number.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects);
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
        if (periods.isClosedOn(sheet.getId(), date)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setDueBy(date.plusDays(sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date)));
        return claim;
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
